# name: within_pair_response_variance
# description: Mean over repeated (set, target) pairs of the within-pair Bernoulli variance p(1-p) of yes responses; observed above null means human answers to the same item are more mixed (less all-or-none) than the model's predicted probabilities, below null means humans are more unanimous than the model.
def test_statistic(df):
    g = df.groupby(["number_set", "target"])["rating"].agg(["mean", "size"])
    g = g[g["size"] >= 2]
    if len(g) == 0:
        return 0.0
    p = g["mean"].to_numpy(dtype=float)
    return float(np.mean(p * (1 - p)))

# name: example_as_target_yes_rate
# description: Yes rate on trials where the target is one of the set's own examples; observed below null means people reject shown examples more often than the model (which treats examples as near-certain members) predicts.
def test_statistic(df):
    parts = df["number_set"].astype(str).str.split(",", expand=True)
    ex = parts.apply(pd.to_numeric, errors="coerce").to_numpy(dtype=float)
    t = df["target"].astype(float).to_numpy()[:, None]
    hit = (ex == t).any(axis=1)
    if hit.sum() == 0:
        return 0.0
    return float(df["rating"].astype(float).to_numpy()[hit].mean())

# name: yes_rate_trial_slope
# description: OLS slope of yes response on trial_index (per 100 trials) across all trials; observed below null means people say yes less as the session goes on (a fatigue/criterion drift the stationary model cannot produce), above null means rising yes rate.
def test_statistic(df):
    x = df["trial_index"].astype(float).to_numpy() / 100.0
    y = df["rating"].astype(float).to_numpy()
    xc = x - x.mean()
    den = (xc ** 2).sum()
    if den == 0:
        return 0.0
    return float((xc * (y - y.mean())).sum() / den)
